import { v7 as uuidv7 } from 'uuid'
import { beforeCreate, type BaseModel } from '@adonisjs/lucid/orm'
import type { NormalizeConstructor } from '@adonisjs/core/types/helpers'

/**
 * Gives a model a UUIDv7 primary key generated by the application before
 * insertion, whatever the PostgreSQL version (ADR 0002). Every model uses it.
 */
export function withUuidV7<Model extends NormalizeConstructor<typeof BaseModel>>(
  superclass: Model
) {
  class ModelWithUuidV7 extends superclass {
    static selfAssignPrimaryKey = true

    @beforeCreate()
    static assignUuidV7(row: ModelWithUuidV7) {
      const primaryKey = (row.constructor as typeof BaseModel).primaryKey
      if (!row.$getAttribute(primaryKey)) {
        row.$setAttribute(primaryKey, uuidv7())
      }
    }
  }

  return ModelWithUuidV7
}
